PRAGMA page_size=4096;
PRAGMA journal_mode=DELETE;
PRAGMA synchronous=EXTRA;
PRAGMA foreign_keys=ON;
BEGIN EXCLUSIVE;
CREATE TABLE shark_store(singleton INTEGER PRIMARY KEY CHECK(singleton=1),store_id TEXT NOT NULL CHECK(length(store_id)=36),world_id TEXT NOT NULL CHECK(length(world_id)=36),schema_version INTEGER NOT NULL CHECK(schema_version=3)) STRICT;
CREATE TABLE shark_accounts(account_id TEXT PRIMARY KEY NOT NULL CHECK(length(account_id)=36),revoked INTEGER NOT NULL CHECK(revoked IN(0,1)),roster_revision INTEGER NOT NULL CHECK(roster_revision>=1),operation_sequence INTEGER NOT NULL CHECK(operation_sequence>=0)) STRICT;
CREATE TABLE shark_certificates(certificate BLOB PRIMARY KEY NOT NULL CHECK(length(certificate)=32),account_id TEXT NOT NULL REFERENCES shark_accounts(account_id),revoked INTEGER NOT NULL CHECK(revoked IN(0,1))) STRICT;
CREATE TABLE shark_characters(character_id TEXT PRIMARY KEY NOT NULL CHECK(length(character_id)=36),account_id TEXT NOT NULL REFERENCES shark_accounts(account_id),entity_id TEXT NOT NULL UNIQUE CHECK(length(entity_id)=36),revision INTEGER NOT NULL CHECK(revision>=1),name TEXT NOT NULL CHECK(length(CAST(name AS BLOB)) BETWEEN 1 AND 256),cell_x INTEGER NOT NULL CHECK(cell_x BETWEEN -2147483648 AND 2147483647),cell_y INTEGER NOT NULL CHECK(cell_y BETWEEN -2147483648 AND 2147483647),cell_z INTEGER NOT NULL CHECK(cell_z BETWEEN -2147483648 AND 2147483647),offset_x REAL NOT NULL CHECK(offset_x>=0 AND offset_x<1024),offset_y REAL NOT NULL CHECK(offset_y>=0 AND offset_y<1024),offset_z REAL NOT NULL CHECK(offset_z>=0 AND offset_z<1024)) STRICT;
CREATE TABLE shark_economy(character_id TEXT PRIMARY KEY NOT NULL REFERENCES shark_characters(character_id),revision INTEGER NOT NULL CHECK(revision>=1),currency INTEGER NOT NULL CHECK(currency BETWEEN 0 AND 1000000000),item_units INTEGER NOT NULL CHECK(item_units BETWEEN 0 AND 1000000000)) STRICT;
CREATE TABLE shark_transfer_receipts(actor_id TEXT NOT NULL REFERENCES shark_accounts(account_id),sequence INTEGER NOT NULL CHECK(sequence>=1),source_id TEXT NOT NULL REFERENCES shark_economy(character_id),target_id TEXT NOT NULL CHECK(length(target_id)=36),expected_source_revision INTEGER NOT NULL CHECK(expected_source_revision>=1),expected_target_revision INTEGER NOT NULL CHECK(expected_target_revision>=1),currency INTEGER NOT NULL CHECK(currency BETWEEN 0 AND 1000000000),item_units INTEGER NOT NULL CHECK(item_units BETWEEN 0 AND 1000000000),status INTEGER NOT NULL CHECK(status BETWEEN 0 AND 5),source_revision INTEGER NOT NULL CHECK(source_revision>=1),source_currency INTEGER NOT NULL CHECK(source_currency BETWEEN 0 AND 1000000000),source_items INTEGER NOT NULL CHECK(source_items BETWEEN 0 AND 1000000000),target_revision INTEGER CHECK(target_revision>=1),target_currency INTEGER CHECK(target_currency BETWEEN 0 AND 1000000000),target_items INTEGER CHECK(target_items BETWEEN 0 AND 1000000000),PRIMARY KEY(actor_id,sequence),CHECK(source_id<>target_id),CHECK(currency>0 OR item_units>0),CHECK((status=4 AND target_revision IS NULL AND target_currency IS NULL AND target_items IS NULL) OR (status<>4 AND target_revision IS NOT NULL AND target_currency IS NOT NULL AND target_items IS NOT NULL))) STRICT;
